-- Sample lesson recordings on course pages. Any https link: a Google Drive or YouTube link, or a video file.
-- For now they point at the recordings already on ohsoed.co.uk; replace them in Admin → Website → Course pages before that site closes.
alter table course_pages drop constraint if exists course_pages_sample_video_url_check;
alter table course_pages add constraint course_pages_sample_video_url_check check (sample_video_url ~ '^https://');
do $$ declare sch uuid; begin
  select id into sch from schools where slug = 'ohsoed'; if sch is null then return; end if;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788505445_KS3%20English%20-%20T3%20Lesson%203', sample_title = 'KS3 English - T3 Lesson 3' where school_id = sch and slug = 'ks3/english-language' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531821_KS3%20Literature%20-%20T7%20Lesson%202.mp4', sample_title = 'KS3 Literature - T7 Lesson 2' where school_id = sch and slug = 'ks3/english-literature' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531877_KS3%20Maths%20-%20T3%20Lesson%202.mp4', sample_title = 'KS3 Maths - T3 Lesson 2' where school_id = sch and slug = 'ks3/maths' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531969_KS3%20Science%20-%20T3%20Lesson%202.mp4', sample_title = 'KS3 Science - T3 Lesson 2' where school_id = sch and slug = 'ks3/science' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788532108_Pre-GCSE%20English%20A%20-%20T2%20Lesson%206.mp4', sample_title = 'Pre-GCSE English A - T2 Lesson 6' where school_id = sch and slug = 'pre-gcse/english-language' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788532256_Pre-GCSE%20Literature%20-%20T4%20Lesson%201.mp4', sample_title = 'Pre-GCSE Literature - T4 Lesson 1' where school_id = sch and slug = 'pre-gcse/english-literature' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788532189_Pre-GCSE%20Geography%20-%20T7%20Lesson%202.mp4', sample_title = 'Pre-GCSE Geography - T7 Lesson 2' where school_id = sch and slug = 'pre-gcse/geography' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788532311_Pre-GCSE%20Maths%20-%20T2%20Lesson%205.mp4', sample_title = 'Pre-GCSE Maths - T2 Lesson 5' where school_id = sch and slug = 'pre-gcse/maths' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788529923_GCSE%20English%20-%20T4%20Lesson%209.mp4', sample_title = 'GCSE English - T4 Lesson 9' where school_id = sch and slug = 'igcse/english-language' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788529687_GCSE%20Business%20Yr2%20-%20T1%20Lesson%202.mp4', sample_title = 'GCSE Business Yr2 - T1 Lesson 2' where school_id = sch and slug = 'igcse/business-studies' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531365_GCSE%20History%20-%20T4%20Lesson%204.mp4', sample_title = 'GCSE History - T4 Lesson 4' where school_id = sch and slug = 'igcse/history' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531464_GCSE%20Maths%20Foundation%20Yr2%20-%20T3%20Lesson%205.mp4', sample_title = 'GCSE Maths Foundation Yr2 - T3 Lesson 5' where school_id = sch and slug = 'igcse/maths-foundation' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531569_GCSE%20Maths%20Higher%20Yr2%20-%20T2%20Lesson%203.mp4', sample_title = 'GCSE Maths Higher Yr2 - T2 Lesson 3' where school_id = sch and slug = 'igcse/maths-higher' and sample_video_url is null;
  update course_pages set sample_video_url = 'https://ohsoed.co.uk/uploads/subject_course_demo_videos/1788531705_GCSE%20Science%20Double%20Yr2%20-%20T2%20Lesson%202.mp4', sample_title = 'GCSE Science Double Yr2 - T2 Lesson 2' where school_id = sch and slug = 'igcse/science-double-award' and sample_video_url is null;
end $$;
